/* @autogenerated */
package net.civeira.phylax.feature.oauth.mfa.infrastructure.driven;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.testing.sql.H2Database;

/** The recovery codes of the second factor consumed with the production sql on h2. */
class RecoveryCodeConsumptionSqlAdapterUnitTest {
  private H2Database db;
  private RecoveryCodeConsumptionSqlAdapter adapter;

  @BeforeEach
  void setUp() {
    db = new H2Database();
    adapter = new RecoveryCodeConsumptionSqlAdapter(db.dataSource());
    // The users belong to the identity model: only the codes are needed here.
    db.execute("SET REFERENTIAL_INTEGRITY FALSE");
    db.execute("INSERT INTO access_user_mfa_recovery_code (uid, version, code_hash, created_at,"
        + " `user`) VALUES ('code-1', 0, 'hash-1', CURRENT_TIMESTAMP, 'user-1')");
  }

  @Test
  @DisplayName("A recovery code is consumed only once")
  void consumed_once() {
    Assertions.assertTrue(adapter.consume("code-1", "user-1"));
    Assertions.assertFalse(adapter.consume("code-1", "user-1"), "A used code is not valid again");

    Assertions.assertEquals(1,
        db.count("access_user_mfa_recovery_code", "uid = 'code-1' AND used_at IS NOT NULL"));
    Assertions.assertEquals(1, db.count("access_user_mfa_recovery_code", "version = 1"));
  }

  @Test
  @DisplayName("A recovery code is only valid for its user")
  void only_for_its_user() {
    Assertions.assertFalse(adapter.consume("code-1", "user-2"));
    Assertions.assertFalse(adapter.consume("missing", "user-1"));
    Assertions.assertEquals(0, db.count("access_user_mfa_recovery_code", "used_at IS NOT NULL"));
  }
}
